colors = [[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
grid = [[0]*30 for _ in range(30)]
starts=[1,8,15,22,29]
for i,r0 in enumerate(starts):
  for j,c0 in enumerate(starts):
    for dr in range(5):
      for dc in range(5):
        r,c=r0+dr,c0+dc
        if r<30 and c<30 and (dr in (0,4) or dc in (0,4)):
          grid[r][c]=4
        elif r<30 and c<30 and i<4 and j<4:
          grid[r][c]=colors[i][j]
# connect like-colored centers along each row/column: paint only the inter-tile gaps
for i in range(4):
  rr=3+7*i
  for color in set(colors[i]):
    cols=[j for j,v in enumerate(colors[i]) if v==color]
    for a,b in zip(cols,cols[1:]):
      for j in range(a,b):
        for cc in range(1+7*j+5, 1+7*j+7): grid[rr][cc]=color
for j in range(4):
  cc=3+7*j
  col=[colors[i][j] for i in range(4)]
  for color in set(col):
    rows=[i for i,v in enumerate(col) if v==color]
    for a,b in zip(rows,rows[1:]):
      for i in range(a,b):
        for rr in range(1+7*i+5, 1+7*i+7): grid[rr][cc]=color
print('\n'.join(' '.join(map(str,row)) for row in grid))

